use std::io::Write;
use std::mem;
use std::ptr;

/// Database packet header for the custom wire protocol
#[repr(C, packed)]
struct PacketHeader {
    magic: u32,
    version: u8,
    flags: u8,
    payload_len: u16,
    sequence_id: u32,
}

/// Audit log entry written for each query
struct AuditEntry {
    timestamp: u64,
    user_id: u32,
    query_hash: [u8; 32],
    source_ip: [u8; 16],
}

const MAX_PACKET_SIZE: usize = 65535;
const HEADER_SIZE: usize = mem::size_of::<PacketHeader>();
const AUDIT_BUFFER_CAP: usize = 4096;

/// Ring buffer for batching audit log writes
struct AuditRingBuffer {
    buffer: Vec<u8>,
    write_pos: usize,
    capacity: usize,
}

impl AuditRingBuffer {
    fn new(capacity: usize) -> Self {
        AuditRingBuffer {
            buffer: vec![0u8; capacity],
            write_pos: 0,
            capacity,
        }
    }

    /// Append serialized audit entry to ring buffer
    /// Returns number of bytes written
    fn append(&mut self, data: &[u8]) -> usize {
        let available = self.capacity - self.write_pos;
        let to_write = data.len().min(available);
        self.buffer[self.write_pos..self.write_pos + to_write]
            .copy_from_slice(&data[..to_write]);
        self.write_pos += to_write;
        to_write
    }

    fn reset(&mut self) {
        self.write_pos = 0;
    }
}

/// Connection state machine for the database driver
struct DbConnection {
    recv_buffer: Vec<u8>,
    recv_len: usize,
    audit_ring: AuditRingBuffer,
    authenticated: bool,
    user_id: u32,
}

impl DbConnection {
    fn new() -> Self {
        DbConnection {
            recv_buffer: vec![0u8; MAX_PACKET_SIZE],
            recv_len: 0,
            audit_ring: AuditRingBuffer::new(AUDIT_BUFFER_CAP),
            authenticated: false,
            user_id: 0,
        }
    }

    /// Parse incoming packet and extract payload
    /// The header's payload_len field determines how much data to process
    fn parse_packet(&self, raw: &[u8]) -> Option<(PacketHeader, &[u8])> {
        if raw.len() < HEADER_SIZE {
            return None;
        }

        let header: PacketHeader = unsafe {
            ptr::read_unaligned(raw.as_ptr() as *const PacketHeader)
        };

        if header.magic != 0xDB_CA_FE_01 {
            return None;
        }

        // Validate payload length against actual buffer
        let payload_end = HEADER_SIZE + header.payload_len as usize;
        if payload_end > raw.len() {
            return None;
        }

        Some((header, &raw[HEADER_SIZE..payload_end]))
    }

    /// Compute the effective audit record size based on query metadata
    /// Uses the packet flags to determine extended audit fields
    fn compute_audit_size(&self, header: &PacketHeader, payload: &[u8]) -> Option<usize> {
        let base_size = mem::size_of::<AuditEntry>();

        // Flag 0x01: include full query text in audit
        // Flag 0x02: include parameter bindings
        // Flag 0x04: include execution plan hash
        let extended_size = if header.flags & 0x01 != 0 {
            payload.len()
        } else {
            0
        };

        let param_size = if header.flags & 0x02 != 0 {
            // Parameter block length is encoded in first 2 bytes of payload
            if payload.len() >= 2 {
                u16::from_le_bytes([payload[0], payload[1]]) as usize
            } else {
                0
            }
        } else {
            0
        };

        let plan_size = if header.flags & 0x04 != 0 { 64 } else { 0 };

        // Total audit record size computation using checked arithmetic
        // to prevent overflow on any target architecture
        base_size
            .checked_add(extended_size)?
            .checked_add(param_size)?
            .checked_add(plan_size)
    }

    /// Write audit log for the current query operation
    fn write_audit_log(&mut self, header: &PacketHeader, payload: &[u8]) {
        let audit_size = match self.compute_audit_size(header, payload) {
            Some(size) if size <= MAX_PACKET_SIZE * 2 => size,
            _ => return, // Reject oversized or overflowed audit records
        };

        // Allocate temporary buffer for the serialized audit record
        let mut audit_record = vec![0u8; audit_size];

        // Write base audit entry
        let base_size = mem::size_of::<AuditEntry>();
        if audit_record.len() >= base_size {
            let entry = AuditEntry {
                timestamp: 0, // would be real timestamp
                user_id: self.user_id,
                query_hash: [0u8; 32],
                source_ip: [0u8; 16],
            };
            unsafe {
                ptr::write(
                    audit_record.as_mut_ptr() as *mut AuditEntry,
                    entry,
                );
            }
        }

        // Copy extended data into audit record
        if header.flags & 0x01 != 0 && audit_record.len() > base_size {
            let dest = &mut audit_record[base_size..];
            let copy_len = payload.len().min(dest.len());
            dest[..copy_len].copy_from_slice(&payload[..copy_len]);
        }

        // Append to ring buffer for batch flush
        self.audit_ring.append(&audit_record);
    }

    /// Process a received database command
    pub fn process_command(&mut self, raw: &[u8]) -> Result<Vec<u8>, &'static str> {
        let (header, payload) = self.parse_packet(raw)
            .ok_or("invalid packet")?;

        if !self.authenticated && header.flags & 0x80 == 0 {
            return Err("not authenticated");
        }

        // Write audit log before processing
        self.write_audit_log(&header, payload);

        // Process the actual command (simplified)
        let response = match header.version {
            1 => self.handle_v1_query(payload),
            2 => self.handle_v2_query(payload),
            _ => Err("unsupported version"),
        };

        response
    }

    fn handle_v1_query(&self, _payload: &[u8]) -> Result<Vec<u8>, &'static str> {
        Ok(vec![0x01, 0x00, 0x00, 0x00])
    }

    fn handle_v2_query(&self, _payload: &[u8]) -> Result<Vec<u8>, &'static str> {
        Ok(vec![0x02, 0x00, 0x00, 0x00])
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic_packet_processing() {
        let mut conn = DbConnection::new();
        conn.authenticated = true;
        conn.user_id = 42;

        let mut packet = vec![0u8; 64];
        // Magic
        packet[0..4].copy_from_slice(&0xDB_CA_FE_01u32.to_ne_bytes());
        // Version 1
        packet[4] = 1;
        // Flags: audit with query text
        packet[5] = 0x01;
        // Payload length: 52 bytes
        packet[6..8].copy_from_slice(&52u16.to_ne_bytes());
        // Sequence
        packet[8..12].copy_from_slice(&1u32.to_ne_bytes());

        let result = conn.process_command(&packet);
        assert!(result.is_ok());
    }
}
